function _getReserves()
        public
        view
        returns (uint256 rOther, uint256 rThis, uint256 balanceOther)
    {
        PancakeSwapPair mainPair = PancakeSwapPair(_mainPair);
        (uint r0, uint256 r1, ) = mainPair.getReserves();

        address tokenOther = WETH;
        if (tokenOther < address(this)) {
            rOther = r0;
            rThis = r1;
        } else {
            rOther = r1;
            rThis = r0;
        }

        balanceOther = IERC20(tokenOther).balanceOf(_mainPair);
    }

function _transfer(address from, address to, uint256 value) internal {
        if (from == address(0)) {
            revert ERC20InvalidSender(address(0));
        }
        if (to == address(0)) {
            revert ERC20InvalidReceiver(address(0));
        }

        bool isBuy = from == _mainPair;
        bool isSell = to == _mainPair;

        if (!_tradingEnabled) {
            require(whiteList[from] || whiteList[to], "Trading is disabled");
        }

        uint256 finalAmount = value;
        uint256 feeAmount;

        if ((isBuy || isSell) && !whiteList[from] && !whiteList[to]) {
            if(isBuy){
                feeAmount = (value * _buyFeeTax) / 100;
            }else{
               if (_endHighTaxTime == 0 || block.timestamp <= _endHighTaxTime) {
                    feeAmount = (value * _sellHighFeeTax) / 100;
                } else {
                    feeAmount = (value * _sellFeeTax) / 100;
                }
            }
        }

        if (feeAmount > 0) {
            finalAmount = value - feeAmount;
            _update(from, address(this), feeAmount);

            if (!swapping && isSell) {
                _swapAndReward();
            }
        }

        _update(from, to, finalAmount);
    }

function _update(address from, address to, uint256 value) internal virtual {
        if (from == address(0)) {
            // Overflow check required: The rest of the code assumes that totalSupply never overflows
            _totalSupply += value;
        } else {
            uint256 fromBalance = _balances[from];
            if (fromBalance < value) {
                revert ERC20InsufficientBalance(from, fromBalance, value);
            }
            unchecked {
                // Overflow not possible: value <= fromBalance <= totalSupply.
                _balances[from] = fromBalance - value;
            }
        }

        if (to == address(0)) {
            unchecked {
                // Overflow not possible: value <= totalSupply or value <= fromBalance <= totalSupply.
                _totalSupply -= value;
            }
        } else {
            unchecked {
                // Overflow not possible: balance + value is at most totalSupply, which we know fits into a uint256.
                _balances[to] += value;
            }
        }

        emit Transfer(from, to, value);
    }

function _approve(address owner, address spender, uint256 value) internal {
        _approve(owner, spender, value, true);
    }

function _approve(address owner, address spender, uint256 value) internal {
        _approve(owner, spender, value, true);
    }

function _spendAllowance(
        address owner,
        address spender,
        uint256 value
    ) internal virtual {
        uint256 currentAllowance = allowance(owner, spender);
        if (currentAllowance != type(uint256).max) {
            if (currentAllowance < value) {
                revert ERC20InsufficientAllowance(
                    spender,
                    currentAllowance,
                    value
                );
            }
            unchecked {
                _approve(owner, spender, currentAllowance - value, false);
            }
        }
    }

function setWhiteList(
        address[] memory addressList,
        bool w
    ) external onlyOwner {
        for (uint256 i = 0; i < addressList.length; i++) {
            whiteList[addressList[i]] = w;
        }
    }

function startTrading() external onlyOwner {
        require(_endHighTaxTime == 0, "Trading already started");
        _endHighTaxTime = block.timestamp + _highTaxDuration;
        _tradingEnabled = true;
    }

function _swapAndReward() internal swapLock {
        address[] memory path = new address[](2);

        path[0] = address(this);
        path[1] = WETH;
        uint256 balance = balanceOf(address(this));
        if(balance == 0){
            return;
        }

        _approve(address(this), ROUTER, balance);

        swapRouter.swapExactTokensForETHSupportingFeeOnTransferTokens(
            balance,
            0,
            path,
            marketAddress,
            block.timestamp
        );

    }
